-- migrations/0001_initial_schema.sql
-- Esquema inicial de Irakurri: Postgres + Auth + RLScreate extension if not exists "uuid-ossp";-- 1. Adultos (familia y/o profesor/PT)create table profiles (  id uuid references auth.users not null primary key,  role text not null check (role in ('family', 'teacher', 'both')) default 'family',  name text not null,  email text,  created_at timestamptz default now());alter table profiles enable row level security;create policy profiles_own on profiles for all using (auth.uid() = id);-- 2. Clases del profesor/PTcreate table classes (  id uuid default uuid_generate_v4() primary key,  teacher_id uuid references profiles(id) not null,  name text not null,  academic_year text not null,  created_at timestamptz default now());alter table classes enable row level security;create policy classes_teacher on classes for all using (auth.uid() = teacher_id);-- 3. Alumnos (unifica "hijo/a" y "alumno/a"; nombre real obligatorio)create table learners (  id uuid default uuid_generate_v4() primary key,  class_id uuid references classes(id) on delete set null,  guardian_id uuid references profiles(id) on delete set null,  display_name text not null,  full_name text,  age_band text check (age_band in ('6-7', '7-8', '8-9')),  support_flags text[] default '{}',  notes text,  color text,  order_in_class int not null default 0,  created_at timestamptz default now());alter table learners enable row level security;create policy learners_access on learners for all  using (    (class_id in (select id from classes where teacher_id = auth.uid()))    or (guardian_id = auth.uid())  );create index idx_learners_class on learners(class_id);create index idx_learners_guardian on learners(guardian_id);-- migrations/0001_initial_schema_part2.sql-- Esquema inicial de Irakurri (parte 2): fonemas, ítems, sesiones, intentos, maestria-- 4. Catálogo de fonemas (orden didáctico)create table phonemes (  code text primary key,  name text not null,  order_index int not null,  level text not null);alter table phonemes enable row level security;create policy phonemes_read on phonemes for select using (true);-- 5. Catálogo de ítems (lectura pública)create table items (  id uuid default uuid_generate_v4() primary key,  phoneme text references phonemes(code),  level text not null,  type text not null,               -- presentation | syllable | word | inverse | cluster | review  grapheme text not null,  audio_key text,  audio_source text check (audio_source in ('tts', 'human', 'placeholder')),  image_key text,  reviewed_at timestamptz,  phonological_tags text[] default '{}',  distractor_pool jsonb default '[]',  created_at timestamptz default now(),  updated_at timestamptz default now());alter table items enable row level security;create policy items_read on items for select using (true);create index idx_items_phoneme on items(phoneme);create index idx_items_level on items(level);-- 6. Sesiones de juegocreate table sessions (  id uuid default uuid_generate_v4() primary key,  mode text not null check (mode in ('guest', 'family', 'classroom')),  guest_token uuid default uuid_generate_v4(),  class_id uuid references classes(id) on delete set null,  teacher_id uuid references profiles(id) on delete set null,  guardian_id uuid references profiles(id) on delete set null,  level text not null,  settings jsonb not null default '{}',  started_at timestamptz default now(),  ended_at timestamptz);alter table sessions enable row level security;create policy sessions_access on sessions for all  using (    (auth.uid() = teacher_id)    or (auth.uid() = guardian_id)    or (mode = 'guest' and guest_token = current_setting('request.jwt.claims', true)::jsonb ->> 'guest_token')  );-- 7. Participantes de una sesión Gelacreate table session_participants (  id uuid default uuid_generate_v4() primary key,  session_id uuid references sessions(id) on delete cascade not null,  learner_id uuid references learners(id) on delete cascade not null,  order_index int not null,  unique (session_id, learner_id));alter table session_participants enable row level security;create policy session_participants_access on session_participants for all  using (exists (    select 1 from sessions s where s.id = session_id and (      s.teacher_id = auth.uid() or s.guardian_id = auth.uid() or s.mode = 'guest'    )  ));-- 8. Intentos (probas)create table attempts (  id uuid default uuid_generate_v4() primary key,  session_id uuid references sessions(id) on delete cascade not null,  learner_id uuid references learners(id) on delete cascade not null,  item_id uuid references items(id) on delete cascade not null,  chosen text not null,  correct boolean not null,  latency_ms int not null default 0,  created_at timestamptz default now());alter table attempts enable row level security;create policy attempts_access on attempts for all  using (exists (    select 1 from sessions s where s.id = session_id and (      s.teacher_id = auth.uid() or s.guardian_id = auth.uid() or s.mode = 'guest'    )  ));create index idx_attempts_session on attempts(session_id);create index idx_attempts_learner on attempts(learner_id);-- 9. Progreso por fonema y alumnocreate table learner_phoneme_progress (  learner_id uuid references learners(id) on delete cascade not null,  phoneme text references phonemes(code) not null,  attempts int not null default 0,  correct int not null default 0,  state text not null check (state in ('datu_zezena', 'oraindik_ez', 'bidean', 'lortuta')) default 'datu_zezena',  updated_at timestamptz default now(),  primary key (learner_id, phoneme));alter table learner_phoneme_progress enable row level security;create policy learner_phoneme_progress_access on learner_phoneme_progress for all  using (    (learner_id in (select id from learners where guardian_id = auth.uid()))    or (learner_id in (select l.id from learners l join classes c on l.class_id = c.id where c.teacher_id = auth.uid()))  );

